using UnityEngine;

namespace RelayCorridor
{
    /// <summary>
    /// Abstraction over reward calculation strategy.
    /// Two implementations exist:
    ///   HandDesignedReward — coefficients written by a human researcher using OCEAN theory.
    ///   LLMDesignedReward  — coefficients generated by Gemini during the design phase.
    ///                        The LLM is NOT called at runtime. This calculator reads a
    ///                        static JSON file produced during the offline design loop.
    /// Both implementations use identical phase gating. Only coefficient magnitudes differ.
    /// </summary>
    public interface IRewardCalculator
    {
        float ComputeStepReward(RelayAgent agent, CorridorEnvironment env);
        float ComputeEventReward(RelayAgent agent, CorridorEnvironment env, RewardEvent evt);
        string CalculatorType { get; }      // "HandDesigned" or "LLMDesigned"
        string PersonaDescription { get; } // human-readable summary
    }

    public enum RewardEvent
    {
        PadActivated,
        GateOpened,
        CellPickedUp,
        CellDropped,
        CellDelivered,
        EpisodeTimeout,
        AgentPushed
    }
}
